"$PYTHON" "$HELPER" session end --id "$SESSION_ID" || true

# Export DB to JSON for git carry-forward
# stderr warnings (e.g. overwrite-smaller-file safety check) must be visible
"$PYTHON" "$HELPER" export --format json --session "$SESSION_ID" || true

printf 'Harness DB: session %s ended, JSON exported\n' "$SESSION_ID"
'@

$hook_sentinel = @'
#!/usr/bin/env bash
# intent-sentinel-stop.sh — Claude Code Stop hook (command type)
# Consolidated telemetry platform: fires every agent turn, collects
# metrics the commander cannot see, and resurfaces intent when drift
# is detected.
#
# Eight telemetry functions:
#   1. Turns-since-human tracker (resurface intent after 3 agent-only turns)
#   2. Phase transition detector (research→execution warning)
#   3. Context consumption tracker (milestones at 25/50/75%)
#   4. Tool usage profile (every 10 turns)
#   5. Subagent tracker (Agent tool launches + completion)
#   6. Running estimate freshness (stale >30min warning)
#   7. Delegation duty compliance score (6 elements)
#   8. Session duration + work product count (every 20 turns)
#
# Output: ONE consolidated status line every INJECT_INTERVAL turns.
# Additional detail lines when specific thresholds are hit.
#
# Hook contract:
#   - Stop hook, command type (stderr -> shown to agent as feedback)
#   - Exit 0 = allow (always)
#   - Must be fast (<50ms) — fires on every agent turn
#   - Must never crash or hang
#   - Standalone — cannot source aitools-lib.sh
#
# Complements:
#   - estimate-refresh-stop.sh (Lagebeurteilung checkpoint — context growth)
#   - surfacing-duty-stop.sh (incident/ambiguity filing duty)
#   This hook consolidates visibility into a single status line.
#
# KPI definitions (logged to harness DB):
#   - sentinel.turnCount: total turns this session
#   - sentinel.turnsSinceHuman: agent turns since last user input
#   - sentinel.contextPercent: estimated context consumption percentage
#   - sentinel.subagentCount: total subagents launched
#   - sentinel.delegationScore: duty elements present / 6
#   - sentinel.reStaleMinutes: running estimate age in minutes
#   - sentinel.scratchFileCount: files in .scratch/session-*
#
# Platform: macOS + Linux + Windows Git Bash (uname -s dispatch for stat)

set -euo pipefail

# --- Configuration (tune after deployment) ---
TURNS_THRESHOLD=3        # Agent turns without user input before injecting intent
READ_STREAK_THRESHOLD=5  # Consecutive Read/Grep turns to qualify as "research phase"
MAX_INTENT_CHARS=300     # Truncate injected intent to this length
INJECT_INTERVAL=5        # Consolidated status line every N turns
RE_STALE_MINUTES=30      # Running estimate stale threshold (minutes)
# Estimated context model: ~2-5K tokens per turn, ~200K total context
TOKENS_PER_TURN=3500     # Average tokens consumed per turn
TOTAL_CONTEXT=200000     # Estimated total context window

# --- Read JSON from stdin ---
input=$(cat)

# --- Pure-bash JSON field extraction ---
# Same pattern as standing-order-guard.sh / harvest-session.sh.
# Handles simple top-level string values only.
json_field() {
    local json="$1" key="$2"
    local pattern="\"${key}\"[[:space:]]*:[[:space:]]*\"([^\"]*)\""
    if [[ "$json" =~ $pattern ]]; then
        printf '%s' "${BASH_REMATCH[1]}"
    fi
}

session_id=$(json_field "$input" "session_id")
transcript_path=$(json_field "$input" "transcript_path")
cwd=$(json_field "$input" "cwd")

# Both required — silent exit if missing
[ -n "$session_id" ] || exit 0
[ -n "$transcript_path" ] && [ -f "$transcript_path" ] || exit 0

# --- Marker directory ---
marker_dir="/tmp/aitools-sentinel-$session_id"
mkdir -p "$marker_dir" 2>/dev/null || exit 0

# --- Turn counter ---
turn_file="$marker_dir/turn-count"
turn_count=0
if [ -f "$turn_file" ]; then
    turn_count=$(cat "$turn_file" 2>/dev/null || echo "0")
    if ! [[ "$turn_count" =~ ^[0-9]+$ ]]; then turn_count=0; fi
fi
turn_count=$((turn_count + 1))
printf '%d' "$turn_count" > "$turn_file"

# --- Session start marker (for duration tracking) ---
start_file="$marker_dir/session-start"
if [ ! -f "$start_file" ]; then
    date +%s > "$start_file"
fi

# --- Project root ---
project_root=""
if [ -n "$cwd" ]; then
    project_root=$(cd "$cwd" 2>/dev/null && git rev-parse --show-toplevel 2>/dev/null || echo "$cwd")
fi

# --- Accumulator for reminders ---
reminders=""
detail_reminders=""

# ==========================================================================
# FUNCTION 1: Turns-since-human tracker
# ==========================================================================
# Count agent turns since last human message. Only extract intent when
# threshold is hit.

agent_turns_since_human=0
agent_turns_since_human=$(tail -500 "$transcript_path" 2>/dev/null | \
    perl -ne '
        if (/"type"\s*:\s*"human"/ && !/"isSidechain"\s*:\s*true/) {
            $count = 0;
        } elsif (/"type"\s*:\s*"assistant"/ && !/"isSidechain"\s*:\s*true/) {
            $count++;
        }
        END { print $count // 0; }
    ' 2>/dev/null || echo "0")

if ! [[ "$agent_turns_since_human" =~ ^[0-9]+$ ]]; then
    agent_turns_since_human=0
fi

intent_text=""
if [ "$agent_turns_since_human" -ge "$TURNS_THRESHOLD" ]; then
    # Extract the user's last instruction
    last_human_line=$(tail -500 "$transcript_path" 2>/dev/null | \
        perl -ne '
            if (/"type"\s*:\s*"human"/ && !/"isSidechain"\s*:\s*true/) {
                $last = $_;
            }
            END { print $last if $last; }
        ' 2>/dev/null || true)

    if [ -n "$last_human_line" ]; then
        intent_text=$(printf '%s' "$last_human_line" | \
            perl -ne '
                if (/"message"\s*:\s*\{.*?"content"\s*:\s*\[/) {
                    while (/"type"\s*:\s*"text"\s*,\s*"text"\s*:\s*"((?:[^"\\]|\\.)*)"/g) {
                        print $1;
                        last;
                    }
                }
            ' 2>/dev/null || true)

        if [ -n "$intent_text" ]; then
            intent_text=$(printf '%s' "$intent_text" | \
                perl -pe 's/\\n/ /g; s/\\"/"/g; s/\\\\/\\/g; s/\\t/ /g;' \
                2>/dev/null || echo "$intent_text")
        fi
    fi

    # Truncate
    if [ -n "$intent_text" ] && [ "${#intent_text}" -gt "$MAX_INTENT_CHARS" ]; then
        intent_text="${intent_text:0:$MAX_INTENT_CHARS}..."
    fi

    if [ -n "$intent_text" ]; then
        detail_reminders="${detail_reminders}INTENT CHECK (${agent_turns_since_human} turns since user): \"${intent_text}\" -- Still aligned? Confirm with user before shifting from research to execution. "
    fi
fi

# ==========================================================================
# FUNCTION 2: Phase transition detector (Read-heavy -> Write/Edit)
# ==========================================================================

if [ -z "$detail_reminders" ]; then
    recent_tools=$(tail -200 "$transcript_path" 2>/dev/null | \
        perl -ne '
            while (/"type"\s*:\s*"tool_use".*?"name"\s*:\s*"(\w+)"/g) {
                print "$1\n";
            }
            while (/"name"\s*:\s*"(\w+)".*?"type"\s*:\s*"tool_use"/g) {
                print "$1\n";
            }
        ' 2>/dev/null || true)

    if [ -n "$recent_tools" ]; then
        read_streak=0
        saw_write=false
        last_tool=""

        while IFS= read -r tool; do
            case "$tool" in
                Read|Grep|Glob)
                    read_streak=$((read_streak + 1))
                    saw_write=false
                    ;;
                Write|Edit)
                    saw_write=true
                    last_tool="$tool"
                    ;;
                *)
                    read_streak=0
                    saw_write=false
                    ;;
            esac
        done <<< "$recent_tools"

        if [ "$saw_write" = "true" ] && [ "$read_streak" -ge "$READ_STREAK_THRESHOLD" ]; then
            detail_reminders="${detail_reminders}PHASE TRANSITION: ${read_streak}+ Read/Grep calls then ${last_tool}. Confirm with user before continuing execution on repo files. "
        fi
    fi
fi

# ==========================================================================
# FUNCTION 3: Context consumption tracker
# ==========================================================================

context_percent=$((turn_count * TOKENS_PER_TURN * 100 / TOTAL_CONTEXT))
if [ "$context_percent" -gt 100 ]; then context_percent=100; fi

# ==========================================================================
# FUNCTION 4: Tool usage profile (computed on injection turns only)
# ==========================================================================

tool_profile=""
if [ $((turn_count % INJECT_INTERVAL)) -eq 0 ]; then
    tool_profile=$(tail -500 "$transcript_path" 2>/dev/null | \
        perl -ne '
            while (/"type"\s*:\s*"tool_use".*?"name"\s*:\s*"(\w+)"/g) { $c{$1}++; }
            while (/"name"\s*:\s*"(\w+)".*?"type"\s*:\s*"tool_use"/g) { $c{$1}++; }
            END {
                my @parts;
                for my $t (sort { $c{$b} <=> $c{$a} } keys %c) {
                    push @parts, "$c{$t} $t";
                    last if @parts >= 5;
                }
                print join(", ", @parts) if @parts;
            }
        ' 2>/dev/null || true)
fi

# ==========================================================================
# FUNCTION 5: Subagent tracker
# ==========================================================================

subagent_info=""
if [ $((turn_count % INJECT_INTERVAL)) -eq 0 ]; then
    subagent_info=$(tail -1000 "$transcript_path" 2>/dev/null | \
        perl -ne '
            $launched++ if /"type"\s*:\s*"tool_use".*?"name"\s*:\s*"Agent"/;
            $launched++ if /"name"\s*:\s*"Agent".*?"type"\s*:\s*"tool_use"/;
            $complete++ if /"type"\s*:\s*"tool_result"/ && /"name"\s*:\s*"Agent"/;
            $complete++ if /"name"\s*:\s*"Agent"/ && /"type"\s*:\s*"tool_result"/;
            END {
                $launched //= 0;
                $complete //= 0;
                my $running = $launched - $complete;
                $running = 0 if $running < 0;
                print "${launched}L/${complete}C/${running}R" if $launched > 0;
            }
        ' 2>/dev/null || true)
fi

# ==========================================================================
# FUNCTION 6: Running estimate freshness
# ==========================================================================

re_stale_minutes=0
re_status="n/a"
if [ -n "$project_root" ]; then
    estimate=""
    if [ -f "$project_root/.aitools/channel/running-estimate.json" ]; then
        estimate="$project_root/.aitools/channel/running-estimate.json"
    fi

    if [ -n "$estimate" ]; then
        now=$(date +%s)
        if [ "$(uname -s)" = "Darwin" ]; then
            est_mod=$(stat -f %m "$estimate" 2>/dev/null || echo "$now")
        else
            est_mod=$(stat -c %Y "$estimate" 2>/dev/null || echo "$now")
        fi
        est_age=$((now - est_mod))
        re_stale_minutes=$((est_age / 60))
        if [ "$re_stale_minutes" -ge "$RE_STALE_MINUTES" ]; then
            re_status="STALE(${re_stale_minutes}m)"
            detail_reminders="${detail_reminders}Running estimate stale (${re_stale_minutes} min). Update with current state. "
        else
            re_status="fresh(${re_stale_minutes}m)"
        fi
    fi
fi

# ==========================================================================
# FUNCTION 7: Delegation duty compliance score
# ==========================================================================

deleg_score=""
if [ $((turn_count % INJECT_INTERVAL)) -eq 0 ]; then
    # Find the most recent Agent tool_use in transcript tail
    last_agent_prompt=$(tail -500 "$transcript_path" 2>/dev/null | \
        perl -ne '
            if (/"name"\s*:\s*"Agent"/ || /"type"\s*:\s*"tool_use".*?"name"\s*:\s*"Agent"/) {
                $last = $_;
            }
            END { print $last if $last; }
        ' 2>/dev/null || true)

    if [ -n "$last_agent_prompt" ]; then
        deleg_score=$(printf '%s' "$last_agent_prompt" | \
            perl -ne '
                my $score = 0;
                my @missing;
                # 1. Identity
                if (/S[1-9]|you are|your identity|your role/i) { $score++; }
                else { push @missing, "identity"; }
                # 2. Rules instruction
                if (/rules|CLAUDE\.md|\.claude\/rules/i) { $score++; }
                else { push @missing, "rules"; }
                # 3. Skills instruction
                if (/skills|SKILL\.md|shared\/skills/i) { $score++; }
                else { push @missing, "skills"; }
                # 4. Operational learning
                if (/operational learning|carry forward|OL-/i) { $score++; }
                else { push @missing, "OL"; }
                # 5. WRITE_BLOCKED signal
                if (/WRITE_BLOCKED/i) { $score++; }
                else { push @missing, "WRITE_BLOCKED"; }
                # 6. Access workaround
                if (/explicit paths|Glob\/Grep|cross-repo|OL-O12/i) { $score++; }
                else { push @missing, "access"; }
                my $missing_str = @missing ? " missing:" . join(",", @missing) : "";
                print "${score}/6${missing_str}";
            ' 2>/dev/null || true)
    fi
fi

# ==========================================================================
# FUNCTION 8: Session duration + work product count
# ==========================================================================

session_duration=""
scratch_count=0
commit_count=0
if [ $((turn_count % INJECT_INTERVAL)) -eq 0 ]; then
    # Duration
    session_start=0
    if [ -f "$start_file" ]; then
        session_start=$(cat "$start_file" 2>/dev/null || echo "0")
        if ! [[ "$session_start" =~ ^[0-9]+$ ]]; then session_start=0; fi
    fi
    if [ "$session_start" -gt 0 ]; then
        now=$(date +%s)
        elapsed=$((now - session_start))
        hours=$((elapsed / 3600))
        minutes=$(( (elapsed % 3600) / 60 ))
        if [ "$hours" -gt 0 ]; then
            session_duration="${hours}h${minutes}m"
        else
            session_duration="${minutes}m"
        fi
    fi

    # Scratch file count
    if [ -n "$project_root" ] && [ -d "$project_root/.scratch" ]; then
        session_prefix=$(printf '%s' "$session_id" | cut -c1-10)
        session_dir="$project_root/.scratch/session-$session_prefix"
        if [ -d "$session_dir" ]; then
            scratch_count=0
            for _f in "$session_dir"/*; do
                [ -f "$_f" ] || continue
                scratch_count=$((scratch_count + 1))
            done
        fi
    fi
fi

# ==========================================================================
# CONSOLIDATED STATUS LINE
# ==========================================================================

if [ $((turn_count % INJECT_INTERVAL)) -eq 0 ] && [ "$turn_count" -gt 0 ]; then
    # Build the consolidated status line
    status_parts="Turn ${turn_count} | Ctx ~${context_percent}%"
    status_parts="${status_parts} | ${agent_turns_since_human}t since human"

    if [ -n "$subagent_info" ]; then
        status_parts="${status_parts} | Sub: ${subagent_info}"
    fi

    status_parts="${status_parts} | RE: ${re_status}"

    if [ -n "$deleg_score" ]; then
        status_parts="${status_parts} | Deleg: ${deleg_score}"
    fi

    if [ -n "$session_duration" ]; then
        status_parts="${status_parts} | ${session_duration}, ${scratch_count} files"
    fi

    reminders="[sentinel] ${status_parts}"

    # Add tool profile on detail turns
    if [ -n "$tool_profile" ]; then
        reminders="${reminders} | Tools: ${tool_profile}"
    fi
fi

# --- Append detail reminders (intent/phase/stale) when thresholds hit ---
if [ -n "$detail_reminders" ]; then
    if [ -n "$reminders" ]; then
        reminders="${reminders} || ${detail_reminders}"
    else
        reminders="[sentinel] ${detail_reminders}"
    fi
fi

# --- Output to stderr (shown to agent as feedback) ---
if [ -n "$reminders" ]; then
    printf '%s' "$reminders" >&2

    # --- KPI logging to harness DB (only when injecting) ---
    if [ -n "$project_root" ]; then
        PYTHON=""
        if command -v python3 > /dev/null 2>&1; then
            PYTHON="python3"
        elif command -v python > /dev/null 2>&1; then
            PYTHON="python"
        fi

        if [ -n "$PYTHON" ]; then
            HELPER=""
            if [ -f "$project_root/scripts/harness-db.py" ]; then
                HELPER="$project_root/scripts/harness-db.py"
            elif [ -f "$HOME/repos/aitools/scripts/harness-db.py" ]; then
                HELPER="$HOME/repos/aitools/scripts/harness-db.py"
            fi

            if [ -n "$HELPER" ] && "$PYTHON" -c "import sqlite3" 2>/dev/null; then
                "$PYTHON" "$HELPER" log --session "$session_id" --type sitrep \
                    --agent "intent-sentinel" \
                    --message "$reminders" || true
            fi
        fi
    fi
fi

exit 0
'@

$hook_delegguard = @'
#!/usr/bin/env bash
# delegation-duty-guard.sh — Claude Code PreToolUse hook (matcher: Agent)
# Checks subagent delegation prompts for 6 duty elements and injects
# a corrective reminder via stderr when elements are missing.
#
# OBSERVE mode: always allows (exit 0), reminds on gaps.
# Future: promote to enforce after observation period.
#
# Six delegation duty elements:
#   1. Identity (role name, "you are", etc.)
#   2. Rules instruction (CLAUDE.md, .claude/rules)
#   3. Skills instruction (skills, SKILL.md, shared/skills)
#   4. Operational learning (OL, carry forward)
#   5. WRITE_BLOCKED signal
#   6. Access workaround (explicit paths, Glob/Grep, OL-O12)
#
# Hook contract:
#   - PreToolUse hook, matcher: Agent
#   - Receives JSON on stdin (tool_name, tool_input)
#   - Exit 0 = allow (always, OBSERVE mode)
#   - stderr -> shown to agent as feedback
#   - Must be fast (<50ms)
#   - Must never crash or hang
#   - Standalone — cannot source aitools-lib.sh
#
# KPI definitions (logged to harness DB):
#   - delegation.score: duty elements present / 6
#   - delegation.missing: comma-separated list of missing elements
#   - delegation.promptLength: approximate prompt length
#
# Platform: macOS + Linux + Windows Git Bash

set -euo pipefail

# --- Read JSON from stdin ---
input=$(cat)

# --- Extract tool_input content ---
# The Agent tool_input contains the prompt text. We need to search
# within the full input for delegation duty elements.
# The prompt is inside "tool_input" which contains "prompt" or "task".

# --- Check duty elements using Perl (portable, no grep -P) ---
result=$(printf '%s' "$input" | \
    perl -ne '
        my $score = 0;
        my @missing;
        my @present;

        # 1. Identity (role name)
        if (/S[1-9]|you\s+are|your\s+identity|your\s+role|Your\s+identity/i) {
            $score++; push @present, "identity";
        } else {
            push @missing, "identity";
        }

        # 2. Rules instruction
        if (/rules|CLAUDE\.md|\.claude\/rules/i) {
            $score++; push @present, "rules";
        } else {
            push @missing, "rules";
        }

        # 3. Skills instruction
        if (/skills|SKILL\.md|shared\/skills/i) {
            $score++; push @present, "skills";
        } else {
            push @missing, "skills";
        }

        # 4. Operational learning
        if (/operational\s+learning|carry\s+forward|OL-/i) {
            $score++; push @present, "OL";
        } else {
            push @missing, "OL";
        }

        # 5. WRITE_BLOCKED signal
        if (/WRITE_BLOCKED/) {
            $score++; push @present, "WRITE_BLOCKED";
        } else {
            push @missing, "WRITE_BLOCKED";
        }

        # 6. Access workaround
        if (/explicit\s+paths|Glob\/Grep|cross-repo|OL-O12/i) {
            $score++; push @present, "access";
        } else {
            push @missing, "access";
        }

        print "$score\n";
        print join(",", @missing) . "\n";
        print join(",", @present) . "\n";
    ' 2>/dev/null || echo "0
identity,rules,skills,OL,WRITE_BLOCKED,access
")

# Parse result
score=$(printf '%s' "$result" | head -1)
missing=$(printf '%s' "$result" | head -2 | tail -1)

if ! [[ "$score" =~ ^[0-9]+$ ]]; then score=0; fi

# --- Inject reminder if elements are missing ---
if [ "$score" -lt 6 ] && [ -n "$missing" ]; then
    reminder="[delegation-guard] Delegation ${score}/6 duty elements."
    reminder="${reminder} Missing: ${missing}."

    # Build specific guidance for each missing element
    guidance=""
    case ",$missing," in
        *,identity,*)
            guidance="${guidance} Identity: include role name (e.g. 'You are S3-Alpha')."
            ;;
    esac
    case ",$missing," in
        *,rules,*)
            guidance="${guidance} Rules: instruct subagent to read CLAUDE.md and .claude/rules/."
            ;;
    esac
    case ",$missing," in
        *,skills,*)
            guidance="${guidance} Skills: mention available skills or shared/skills/ path."
            ;;
    esac
    case ",$missing," in
        *,OL,*)
            guidance="${guidance} OL: include operational learning items relevant to the task."
            ;;
    esac
    case ",$missing," in
        *,WRITE_BLOCKED,*)
            guidance="${guidance} WRITE_BLOCKED: signal if subagent cannot write to protected files."
            ;;
    esac
    case ",$missing," in
        *,access,*)
            guidance="${guidance} Access: note cross-repo paths and Glob/Grep workarounds (OL-O12)."
            ;;
    esac

    if [ -n "$guidance" ]; then
        reminder="${reminder}${guidance}"
    fi

    printf '%s' "$reminder" >&2

    # --- KPI logging to harness DB ---
    # Extract session_id from hook input (may not be present in PreToolUse)
    session_id=""
    sid_pattern='"session_id"[[:space:]]*:[[:space:]]*"([^"]*)"'
    if [[ "$input" =~ $sid_pattern ]]; then
        session_id="${BASH_REMATCH[1]}"
    fi

    if [ -n "$session_id" ]; then
        # Find project root for harness-db.py
        project_root=$(git rev-parse --show-toplevel 2>/dev/null || echo "")

        PYTHON=""
        if command -v python3 > /dev/null 2>&1; then
            PYTHON="python3"
        elif command -v python > /dev/null 2>&1; then
            PYTHON="python"
        fi

        if [ -n "$PYTHON" ] && [ -n "$project_root" ]; then
            HELPER=""
            if [ -f "$project_root/scripts/harness-db.py" ]; then
                HELPER="$project_root/scripts/harness-db.py"
            elif [ -f "$HOME/repos/aitools/scripts/harness-db.py" ]; then
                HELPER="$HOME/repos/aitools/scripts/harness-db.py"
            fi

            if [ -n "$HELPER" ] && "$PYTHON" -c "import sqlite3" 2>/dev/null; then
                "$PYTHON" "$HELPER" log --session "$session_id" --type finding \
                    --agent "delegation-guard" \
                    --message "Delegation ${score}/6. Missing: ${missing}" || true
            fi
        fi
    fi
fi

# OBSERVE mode: always allow
exit 0
'@

$hookFiles = @{
    "session-archive.sh" = $hook_archive
    "standing-order-guard.sh" = $hook_guard
    "scratch-init.sh" = $hook_scratch
    "harvest-session.sh" = $hook_harvest
    "sh-file-fixup.sh" = $hook_shfixup
    "surfacing-duty-stop.sh" = $hook_surfacing
    "glossary-skill-guard.sh" = $hook_glossary
    "block-claude-code-guide.sh" = $hook_blockguide
    "tool-ops-session-audit.sh" = $hook_toolops
    "dashboard-serve.sh" = $hook_dashboard
    "estimate-refresh-stop.sh" = $hook_estimrefresh
    "harness-db-sessionstart.sh" = $hook_hdbstart
    "harness-db-sessionend.sh" = $hook_hdbend
    "intent-sentinel-stop.sh" = $hook_sentinel
    "delegation-duty-guard.sh" = $hook_delegguard
}

if ($DryRun) {
    Log "[DRY RUN] Would deploy hooks to ~/.claude/hooks/"
} else {
    foreach ($hName in $hookFiles.Keys) {
        $hDest = Join-Path $hooksDir $hName
        $hResolved = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($hDest)
        [System.IO.File]::WriteAllText($hResolved, $hookFiles[$hName], [System.Text.UTF8Encoding]::new($false))
        LogOk "Deployed hook: $hDest"
    }
}

# Legacy dest vars for settings.json merge below
$hookDest = Join-Path $hooksDir "session-archive.sh"
$guardDest = Join-Path $hooksDir "standing-order-guard.sh"

# --- Embedded preferences (from profile.json at build time) ---
$autoMemory = $false
$alwaysThinking = $true
$effortLevel = "high"
$validEffortLevels = @("low", "medium", "high")

# --- Merge hook + preferences into ~/.claude/settings.json ---
$settingsFile = Join-Path $claudeDir "settings.json"
if (-not (Test-Path $claudeDir)) {
    if (-not $DryRun) {
        New-Item -ItemType Directory -Path $claudeDir -Force | Out-Null
    }
}

# Hook command uses Unix-style path (hooks run in bash even on Windows)
$hookDestPath = Join-Path $hooksDir "session-archive.sh"
$hookDestUnix = $hookDestPath -replace '\\', '/'
$hookCmd = "bash `"$hookDestUnix`""

$shfixupDestUnix = $shfixupDest -replace '\\', '/'
$shfixupCmd = "bash `"$shfixupDestUnix`""

$surfacingDestUnix = $surfacingDest -replace '\\', '/'
$surfacingCmd = "bash `"$surfacingDestUnix`""

# Read existing settings
$settings = @{}
$corrupt = $false
if (Test-Path $settingsFile) {
    try {
        $raw = Get-Content $settingsFile -Raw
        $settings = ConvertPSObjectToHashtable ($raw | ConvertFrom-Json)
    } catch {
        $corrupt = $true
        LogWarn "$settingsFile could not be parsed ($_)"
    }
}
$beforeKeys = @($settings.Keys)

# --- Merge hooks ---
if (-not $settings.ContainsKey("hooks")) { $settings["hooks"] = @{} }

# Helper: ensure exactly one entry for a hookId in an event array.
# Updates the command if found, adds if not, deduplicates extras.
function MergeHookEntry($eventName, $hookIdentifier, $matcherValue, $cmd, $hookType) {
    if (-not $hookType) { $hookType = "command" }
    if (-not $settings["hooks"].ContainsKey($eventName)) {
        $settings["hooks"][$eventName] = @()
    }
    $arr = @($settings["hooks"][$eventName])

    # Find first matching entry and update it
    $found = $false
    foreach ($rule in $arr) {
        if ($rule -is [System.Collections.Hashtable] -and $rule.ContainsKey("hooks")) {
            foreach ($h in @($rule["hooks"])) {
                if ($h -is [System.Collections.Hashtable] -and $h.ContainsKey("command") -and $h["command"] -match [regex]::Escape($hookIdentifier)) {
                    if (-not $found) {
                        $h["command"] = $cmd
                        $h["type"] = $hookType
                        $rule["matcher"] = $matcherValue
                        $found = $true
                    }
                }
            }
        }
    }
    if (-not $found) {
        $arr += @{
            matcher = $matcherValue
            hooks   = @(@{ type = $hookType; command = $cmd })
        }
    }

    # Normalize: ensure hooks field in each rule is always an array
    # (fixes corruption from prior buggy writes where ConvertTo-Json unwrapped single-element arrays)
    foreach ($rule in $arr) {
        if ($rule -is [System.Collections.Hashtable] -and $rule.ContainsKey("hooks") -and $rule["hooks"] -isnot [array]) {
            $rule["hooks"] = @($rule["hooks"])
        }
    }

    # Deduplicate: keep only the first entry matching hookIdentifier
    $seen = $false
    $deduped = @()
    foreach ($rule in $arr) {
        $isMatch = $false
        if ($rule -is [System.Collections.Hashtable] -and $rule.ContainsKey("hooks")) {
            foreach ($h in @($rule["hooks"])) {
                if ($h -is [System.Collections.Hashtable] -and $h.ContainsKey("command") -and $h["command"] -match [regex]::Escape($hookIdentifier)) {
                    $isMatch = $true
                    break
                }
            }
        }
        if ($isMatch -and $seen) { continue }
        if ($isMatch) { $seen = $true }
        $deduped += $rule
    }
    $settings["hooks"][$eventName] = $deduped
}

# SessionEnd: session archive
MergeHookEntry "SessionEnd" "session-archive.sh" "" $hookCmd

# PreToolUse: standing order guard
$guardDestUnix = $guardDest -replace '\\', '/'
$guardCmd = "bash `"$guardDestUnix`""
MergeHookEntry "PreToolUse" "standing-order-guard.sh" "Bash" $guardCmd

# PreToolUse: glossary skill guard
$glossaryDestUnix = (Join-Path $hooksDir "glossary-skill-guard.sh") -replace '\\', '/'
$glossaryCmd = "bash `"$glossaryDestUnix`""
MergeHookEntry "PreToolUse" "glossary-skill-guard.sh" "Read|Grep" $glossaryCmd
MergeHookEntry "PostToolUse" "sh-file-fixup.sh" "Write|Edit" $shfixupCmd
MergeHookEntry "Stop" "surfacing-duty-stop.sh" "" $surfacingCmd

# PreToolUse: block claude-code-guide subagent
$blockGuideDestUnix = $blockGuideDest -replace '\\', '/'
$blockGuideCmd = "bash `"$blockGuideDestUnix`""
MergeHookEntry "PreToolUse" "block-claude-code-guide.sh" "Agent" $blockGuideCmd

# SessionEnd: tool-ops session audit
$toolOpsAuditDestUnix = $toolOpsAuditDest -replace '\\', '/'
$toolOpsAuditCmd = "bash `"$toolOpsAuditDestUnix`""
MergeHookEntry "SessionEnd" "tool-ops-session-audit.sh" "" $toolOpsAuditCmd

# SessionStart: dashboard server
$dashboardDestUnix = $dashboardDest -replace '\\', '/'
$dashboardCmd = "bash `"$dashboardDestUnix`""
MergeHookEntry "SessionStart" "dashboard-serve.sh" "" $dashboardCmd

# Stop: estimate refresh + Lagebeurteilung
$estimateRefreshDestUnix = $estimateRefreshDest -replace '\\', '/'
$estimateRefreshCmd = "bash `"$estimateRefreshDestUnix`""
MergeHookEntry "Stop" "estimate-refresh-stop.sh" "" $estimateRefreshCmd

# Stop: intent sentinel (consolidated telemetry)
$sentinelDestUnix = $sentinelDest -replace '\\', '/'
$sentinelCmd = "bash `"$sentinelDestUnix`""
MergeHookEntry "Stop" "intent-sentinel-stop.sh" "" $sentinelCmd

# PreToolUse: delegation duty guard
$delegGuardDestUnix = $delegGuardDest -replace '\\', '/'
$delegGuardCmd = "bash `"$delegGuardDestUnix`""
MergeHookEntry "PreToolUse" "delegation-duty-guard.sh" "Agent" $delegGuardCmd

# --- Track old values for change reporting ---
$oldAutoMemory = $settings["autoMemoryEnabled"]
$oldAlwaysThinking = $settings["alwaysThinkingEnabled"]
$oldEffortLevel = $settings["effortLevel"]

# --- Merge claude preferences ---
$settings["autoMemoryEnabled"] = $autoMemory
$settings["alwaysThinkingEnabled"] = $alwaysThinking
if ($effortLevel) { $settings["effortLevel"] = $effortLevel }

# --- Detect preference changes ---
$prefChanges = @()
if ($oldAutoMemory -ne $settings["autoMemoryEnabled"]) {
    $oldVal = if ($null -ne $oldAutoMemory) { $oldAutoMemory } else { "(not set)" }
    $prefChanges += "autoMemoryEnabled: $oldVal -> $($settings['autoMemoryEnabled'])"
}
if ($oldAlwaysThinking -ne $settings["alwaysThinkingEnabled"]) {
    $oldVal = if ($null -ne $oldAlwaysThinking) { $oldAlwaysThinking } else { "(not set)" }
    $prefChanges += "alwaysThinkingEnabled: $oldVal -> $($settings['alwaysThinkingEnabled'])"
}
if ($effortLevel -and $oldEffortLevel -ne $settings["effortLevel"]) {
    $oldEL = if ($oldEffortLevel) { $oldEffortLevel } else { "(not set)" }
    $prefChanges += "effortLevel: $oldEL -> $($settings['effortLevel'])"
}

# --- Clobber detection ---
$managedKeys = @("hooks", "autoMemoryEnabled", "alwaysThinkingEnabled", "effortLevel")
$lostKeys = @($beforeKeys | Where-Object { $_ -notin $settings.Keys })

if ($DryRun) {
    Log "[DRY RUN] $settingsFile`: merge"
    Log "  Managed fields: $($managedKeys -join ', ')"
    if ($lostKeys.Count -gt 0) {
        LogWarn "[DRY RUN] CLOBBER: would lose non-managed fields: $($lostKeys -join ', ')"
    }
    if ($corrupt) {
        LogWarn "[DRY RUN] File is corrupt -- -Force required to overwrite"
    }
    Log "[DRY RUN] SessionEnd hook: $hookCmd"
    Log "[DRY RUN] PreToolUse hook: $guardCmd"
    Log "[DRY RUN] autoMemoryEnabled: $autoMemory"
    Log "[DRY RUN] alwaysThinkingEnabled: $alwaysThinking"
    if ($effortLevel) { Log "[DRY RUN] effortLevel: $effortLevel" }
} else {
    if ($corrupt -and -not $Force) {
        LogError "$settingsFile is corrupt. Use -Force to overwrite, or fix manually."
        Write-Summary "ERROR" "claude hooks" "settings corrupt"
    } elseif ($lostKeys.Count -gt 0 -and -not $Force) {
        LogError "$settingsFile merge would lose fields: $($lostKeys -join ', '). Use -Force to proceed."
        Write-Summary "ERROR" "claude hooks" "merge would lose fields"
    } else {
        if ($corrupt) { LogWarn "Proceeding with -Force on corrupt file" }
        if ($lostKeys.Count -gt 0) { LogWarn "Proceeding with -Force, losing fields: $($lostKeys -join ', ')" }

        $mergedJson = $settings | ConvertTo-Json -Depth 10
        $mergedNorm = Normalize-JsonForComparison $settings -Depth 10
        $existingNorm = if (Test-Path $settingsFile) {
            try { Normalize-JsonForComparison (ConvertPSObjectToHashtable (Get-Content $settingsFile -Raw -ErrorAction Stop | ConvertFrom-Json)) -Depth 10 }
            catch { $null }
        } else { $null }
        if ($mergedNorm -eq $existingNorm) {
            LogOk "Settings unchanged: $settingsFile"
        } else {
            $resolvedPath = $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($settingsFile)
            [System.IO.File]::WriteAllText($resolvedPath, $mergedJson, [System.Text.UTF8Encoding]::new($false))
            $hooksChanged = $true

            # Post-write validation
            try {
                $vContent = [System.IO.File]::ReadAllText($resolvedPath)
                $vParsed = $vContent | ConvertFrom-Json
                $requiredKeys = @("hooks", "autoMemoryEnabled", "alwaysThinkingEnabled")
                if ($effortLevel) { $requiredKeys += "effortLevel" }
                foreach ($rk in $requiredKeys) {
                    if (-not ($vParsed.PSObject.Properties.Name -contains $rk)) {
                        LogError "Validation failed: $settingsFile missing required field '$rk'"
                    }
                }
            } catch {
                LogError "Validation failed: $settingsFile is not valid JSON -- $_"
            }

            # Validate hook deduplication
            $seCount = @($vParsed.hooks.SessionEnd | Where-Object { $_.hooks.command -match 'session-archive\.sh' }).Count
            $ptCount = @($vParsed.hooks.PreToolUse | Where-Object { $_.hooks.command -match 'standing-order-guard\.sh' }).Count
            $glCount = @($vParsed.hooks.PreToolUse | Where-Object { $_.hooks.command -match 'glossary-skill-guard\.sh' }).Count
            if ($seCount -ne 1) { LogError "Validation failed: expected 1 SessionEnd hook, got $seCount" }
            if ($ptCount -ne 1) { LogError "Validation failed: expected 1 PreToolUse standing-order-guard hook, got $ptCount" }
            if ($glCount -ne 1) { LogError "Validation failed: expected 1 PreToolUse glossary-skill-guard hook, got $glCount" }
            $bgCount = @($vParsed.hooks.PreToolUse | Where-Object { $_.hooks.command -match 'block-claude-code-guide\.sh' }).Count
            if ($bgCount -ne 1) { LogError "Validation failed: expected 1 PreToolUse block-claude-code-guide hook, got $bgCount" }
            $toaCount = @($vParsed.hooks.SessionEnd | Where-Object { $_.hooks.command -match 'tool-ops-session-audit\.sh' }).Count
            if ($toaCount -ne 1) { LogError "Validation failed: expected 1 SessionEnd tool-ops-session-audit hook, got $toaCount" }
            $dashCount = @($vParsed.hooks.SessionStart | Where-Object { $_.hooks.command -match 'dashboard-serve\.sh' }).Count
            if ($dashCount -ne 1) { LogError "Validation failed: expected 1 SessionStart dashboard-serve hook, got $dashCount" }
            $erCount = @($vParsed.hooks.Stop | Where-Object { $_.hooks.command -match 'estimate-refresh-stop\.sh' }).Count
            if ($erCount -ne 1) { LogError "Validation failed: expected 1 Stop estimate-refresh-stop hook, got $erCount" }
            $sentCount = @($vParsed.hooks.Stop | Where-Object { $_.hooks.command -match 'intent-sentinel-stop\.sh' }).Count
            if ($sentCount -ne 1) { LogError "Validation failed: expected 1 Stop intent-sentinel hook, got $sentCount" }
            $dgCount = @($vParsed.hooks.PreToolUse | Where-Object { $_.hooks.command -match 'delegation-duty-guard\.sh' }).Count
            if ($dgCount -ne 1) { LogError "Validation failed: expected 1 PreToolUse delegation-duty-guard hook, got $dgCount" }

            # Validate hook schema: command-type must have command,
            # prompt-type must have prompt (not command).
            foreach ($eventName in $vParsed.hooks.PSObject.Properties.Name) {
                foreach ($rule in @($vParsed.hooks.$eventName)) {
                    foreach ($h in @($rule.hooks)) {
                        if ($h.type -eq "command" -and -not $h.command) {
                            LogError "Validation failed: $eventName hook has type 'command' but no command field"
                        }
                        if ($h.type -eq "prompt") {
                            if (-not $h.prompt) {
                                LogError "Validation failed: $eventName hook has type 'prompt' but no prompt field. Prompt-type hooks require a static string."
                            }
                            if ($h.command) {
                                LogError "Validation failed: $eventName hook has type 'prompt' with command field. Use type 'command' for scripts."
                            }
                        }
                    }
                }
            }

            LogOk "Settings deployed to $settingsFile"
            Log "  SessionEnd hook: $hookCmd"
            Log "  PreToolUse hook: $guardCmd"
            Log "  autoMemoryEnabled: $autoMemory"
            Log "  alwaysThinkingEnabled: $alwaysThinking"
            $effortDisplay = if ($effortLevel) { $effortLevel } else { "(not set)" }
            Log "  effortLevel: $effortDisplay"
            if ($prefChanges.Count -gt 0) {
                Emit-MergeDetails -Changes $prefChanges -ToolName "claude hooks"
            }
        }
    }
}
if ($errors -gt 0) {
    Log "FAILED with $errors error(s). See log: $logFile" "error"
    exit 1
} elseif ($warnings -gt 0) {
    Log "COMPLETED with $warnings warning(s)" "warn"
    exit 0
} else {
    Log "COMPLETED successfully" "ok"
    exit 0
}
